 en:{checkerSettings:'Checker settings',checks:'Kanji checking',checksHint:'Readability, shape and stroke order',japaneseModel:'Japanese model',modelReady:'Model ready',modelMissing:'Model not downloaded',modelLoading:'Downloading model…',modelError:'Could not download model',modelHint:'The model is needed for readability checking.',modelDownload:'Download model',modelState:'Model state in the prototype',shapeGroup:'Shape similarity',compensationGroup:'Compensations',budgetGroup:'Combined budget',rulesGroup:'Dictionary rules',checksGroup:'Enabled checkers',resetSettings:'Reset parameters',settingsPreview:'Values change only in this prototype.',zeroHelp:'0 disables a compensation. Zero total budget removes only the combined limit.',paramMatch:'Similarity threshold',paramDistance:'Distance tolerance',paramTranslation:'Translation',paramSize:'Size',paramStretchX:'Horizontal stretch',paramStretchY:'Vertical stretch',paramRotation:'Rotation',paramShear:'Shear',paramJitter:'Hand jitter',paramBudget:'Combined correction budget',paramLength:'Stroke length difference',paramConnection:'Stroke connections',paramProtrusion:'Stroke protrusions',ruleStructure:'Check structure',ruleOrder:'Check order',ruleDirection:'Check direction'}
