let settingsReturn='home',modelState='ready';
const parameterGroups={shapeGroup:[['match','paramMatch',72,1,100,1,'%'],['distance','paramDistance',5,1,15,1,'%']],compensationGroup:[['translation','paramTranslation',12,0,100,1,'%'],['size','paramSize',30,0,200,1,'%'],['stretchX','paramStretchX',15,0,100,1,'%'],['stretchY','paramStretchY',15,0,100,1,'%'],['rotation','paramRotation',8,0,20,1,'°'],['shear','paramShear',8,0,20,1,'°'],['jitter','paramJitter',.5,0,5,.1,'%']],budgetGroup:[['budget','paramBudget',35,0,100,1,'%']],rulesGroup:[['length','paramLength',5,0,30,1,'%'],['connection','paramConnection',5,0,30,1,'%'],['protrusion','paramProtrusion',3,0,30,1,'%']]};
let parameterValues=Object.fromEntries(Object.values(parameterGroups).flat().map(([id,,value])=>[id,value]));
let enabledChecks={readability:true,shape:true,strokes:true,ruleStructure:true,ruleOrder:false,ruleDirection:false};
function settingsView(){const key={ready:'modelReady',missing:'modelMissing',loading:'modelLoading',error:'modelError'}[modelState];return header(t('settings'),'home')+`<div class="settings-content"><button class="settings-entry" data-action="go:checker-settings">${icon('check')}<span><strong>${t('checks')}</strong><small>${t('checksHint')}</small></span>${icon('chevron')}</button><section class="settings-panel"><h3>${t('japaneseModel')}</h3><p class="model-status ${modelState==='error'?'is-error':''}" role="status">${modelState==='ready'?'✓ ':modelState==='error'?'! ':''}${t(key)}</p><p>${t('modelHint')}</p>${modelState==='ready'?'':`<button class="tonal-button" data-settings="model">${t(modelState==='error'?'retry':'modelDownload')}</button>`}</section></div>`;}
function checkerToggle(key){return `<label class="settings-toggle"><span>${t(key)}</span><input type="checkbox" role="switch" data-setting-toggle="${key}" ${enabledChecks[key]?'checked':''}></label>`;}
function checkerSettingsView(){return header(t('checkerSettings'),settingsReturn==='practice'?'practice':'settings')+`<div class="settings-content"><p class="settings-note">${t('settingsPreview')}</p><section class="settings-panel"><h3>${t('checksGroup')}</h3>${['readability','shape','strokes'].map(checkerToggle).join('')}</section>${Object.entries(parameterGroups).map(([name,items],i)=>`<details class="settings-panel" ${i===0?'open':''}><summary>${t(name)}</summary>${name==='rulesGroup'?checkerToggle('ruleStructure'):''}${items.map(([id,label,value,min,max,step,unit])=>`<label class="settings-parameter"><span>${t(label)}</span><span class="settings-value"><input type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${parameterValues[id]}" data-parameter="${id}" aria-label="${t(label)}"><span>${unit}</span></span></label>`).join('')}${name==='compensationGroup'||name==='budgetGroup'?`<p class="settings-note">${t('zeroHelp')}</p>`:''}</details>`).join('')}<section class="settings-panel">${['ruleOrder','ruleDirection'].map(checkerToggle).join('')}</section><button class="tonal-button" data-settings="reset">${icon('undo')}${t('resetSettings')}</button></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-settings]');if(!b)return;if(b.dataset.settings==='model'){modelState='ready';render()}if(b.dataset.settings==='reset')showModal(t('resetSettings'),`<p>${t('settingsPreview')}</p>`,[{label:t('cancel'),fn:closeModal},{label:t('resetSettings'),fn:()=>{parameterValues=Object.fromEntries(Object.values(parameterGroups).flat().map(([id,,value])=>[id,value]));closeModal();render()}}]);});
document.addEventListener('change',e=>{if(e.target.dataset.settingToggle)enabledChecks[e.target.dataset.settingToggle]=e.target.checked;if(e.target.dataset.parameter){const value=Number(e.target.value);if(e.target.checkValidity()&&Number.isFinite(value))parameterValues[e.target.dataset.parameter]=value;else e.target.value=parameterValues[e.target.dataset.parameter];}if(e.target.id==='model-state'){modelState=e.target.value;render()}});
